-- Alimentos nuevos que usan estas recetas
insert into public.content_foods (id, name, p, c, f, tags)
select id, name, p, c, f, tags from jsonb_populate_recordset(null::public.content_foods, $arc$[{"id": "fresas", "name": "Fresas", "p": 0.7, "c": 7.7, "f": 0.3, "tags": []}, {"id": "frutosRojos", "name": "Frutos rojos congelados", "p": 1, "c": 9, "f": 0.3, "tags": []}, {"id": "chia", "name": "Semillas de chía", "p": 17, "c": 8, "f": 31, "tags": []}, {"id": "udon", "name": "Fideos udon (cocidos)", "p": 2.6, "c": 21, "f": 0.4, "tags": ["gluten"]}, {"id": "pastaLentejas", "name": "Pasta de lentejas rojas", "p": 25, "c": 50, "f": 2.5, "tags": []}, {"id": "lomoCerdo", "name": "Lomo de cerdo magro", "p": 21, "c": 0, "f": 6, "tags": ["cerdo"]}, {"id": "hambTernera", "name": "Hamburguesa de ternera magra", "p": 20, "c": 1, "f": 10, "tags": []}, {"id": "salsaBBQ", "name": "Salsa barbacoa", "p": 1, "c": 40, "f": 0.5, "tags": []}]$arc$::jsonb)
on conflict (id) do update set name = excluded.name, p = excluded.p, c = excluded.c, f = excluded.f, tags = excluded.tags;

-- 17 recetas nuevas (si ya existen, se actualiza el texto)
insert into public.content_recipes (id, slot, mode, name, items, how, steps, plate, tupper, active, sort)
select id, slot, mode, name, items, how, steps, plate, tupper, active, sort from jsonb_populate_recordset(null::public.content_recipes, $arc$[{"id": "rl01", "slot": "desayuno", "mode": "sencilla", "name": "Bol de yogur frutos del bosque", "items": [["yogurProt", "p"], ["frutosRojos", 100], ["platano", "c"], ["chia", 10]], "how": "Yogur en un bol, plátano en rodajas haciendo una media luna, frutos rojos congelados en una esquina y chía y canela por encima. Usa yogur sin azúcares añadidos: los de sabor suelen llevar mucho.", "steps": [], "plate": "Espolvorea la canela solo en una mitad: queda precioso con el contraste.", "tupper": false, "active": true, "sort": 100}, {"id": "rl02", "slot": "comida", "mode": "sanji", "name": "Bowl de salmón, lentejas y ñoquis", "items": [["salmon", "p"], ["legumbres", 100], ["noquis", "c"], ["verduras", 120]], "how": "", "steps": ["Salmón al horno o airfryer a 200 °C unos 10–12 minutos con sal y limón.", "Dora los ñoquis en una sartén antiadherente sin aceite hasta que estén crujientes por fuera.", "Monta el bol con lechuga, pepino, las lentejas de bote (las del Mercadona van genial) bien enjuagadas, los ñoquis y el salmón encima."], "plate": "", "tupper": true, "active": true, "sort": 101}, {"id": "rl03", "slot": "comida", "mode": "sencilla", "name": "Ensalada de pollo, garbanzos y rúcula", "items": [["pollo", "p"], ["legumbres", "c"], ["verduras", 120], ["aguacate", "f"]], "how": "Pollo a la plancha en tiras, garbanzos de bote enjuagados, rúcula, pepino y el aguacate en gajos. Sal en escamas por encima. Los garbanzos de bote del Mercadona van genial; enjuágalos bien.", "steps": [], "plate": "", "tupper": true, "active": true, "sort": 102}, {"id": "rl04", "slot": "comida", "mode": "sencilla", "name": "Fusilli de lentejas con pollo", "items": [["pastaLentejas", "c"], ["pollo", "p"], ["verduras", 120], ["aguacate", "f"]], "how": "Cuece la pasta de lentejas 7–8 minutos (se pasa rápido). Sirve con el pollo a la plancha, canónigos, pepino y aguacate. Sin gluten y con un montón de proteína. Mira que la pasta sea 100% harina de lentejas, sin mezcla de trigo.", "steps": [], "plate": "", "tupper": true, "active": true, "sort": 103}, {"id": "rl05", "slot": "desayuno", "mode": "sencilla", "name": "Avena cremosa de plátano y arándanos", "items": [["avena", "c"], ["claras", "p"], ["platano", 50], ["arandanos", 50], ["chia", 5]], "how": "Mezcla la avena con las claras, un chorrito de leche o agua y la chía. Micro 2 minutos removiendo a la mitad. Encima, plátano, arándanos y canela.", "steps": [], "plate": "", "tupper": false, "active": true, "sort": 104}, {"id": "rl06", "slot": "comida", "mode": "sanji", "name": "Udon de pollo con huevo poché", "items": [["udon", "c"], ["pollo", "p"], ["huevo", 60], ["verduras", 100], ["aove", "f"]], "how": "", "steps": ["Pollo en dados a la plancha con el aceite hasta que se dore bien.", "Saltea las espinacas 1 minuto en la misma sartén y calienta el udon 2 minutos con un chorrito de soja.", "Huevo poché: agua casi hirviendo con vinagre, remolino y 3 minutos. Ponlo encima de todo y rompe la yema al comer."], "plate": "", "tupper": false, "active": true, "sort": 105}, {"id": "rl07", "slot": "comida", "mode": "sencilla", "name": "Táper de cerdo con batata asada", "items": [["lomoCerdo", "p"], ["batata", "c"], ["patata", 100], ["verduras", 200], ["aove", "f"]], "how": "Batata en rodajas y patata en dados al horno a 200 °C 25 minutos. Verduras salteadas (judías, brócoli, champiñón, pimiento) y el lomo en tiras a la plancha. Perfecto para llevar.", "steps": [], "plate": "", "tupper": true, "active": true, "sort": 106}, {"id": "rl08", "slot": "cena", "mode": "sencilla", "name": "Revuelto de atún, tomate y aguacate", "items": [["huevo", 120], ["atun", "p"], ["verduras", 100], ["aguacate", "f"]], "how": "Revuelve los huevos con el atún escurrido a fuego medio. Sirve con tomate en rodajas y aguacate con sal.", "steps": [], "plate": "", "tupper": false, "active": true, "sort": 107}, {"id": "rl09", "slot": "merienda", "mode": "sencilla", "name": "Tortitas dúo de atún con fresas", "items": [["tortitasArroz", "c"], ["atun", "p"], ["cottage", 30], ["aguacate", "f"], ["salsaBBQ", 10], ["fresas", 100]], "how": "Una tortita con cottage y atún; la otra con aguacate machacado, atún y un hilo de salsa barbacoa. Fresas al lado. Tortitas solo de arroz o maíz y sal, sin aceite de palma ni azúcar. Ojo con la barbacoa: casi la mitad es azúcar, usa poca o una zero.", "steps": [], "plate": "Dos tortitas, dos sabores: así no te aburres nunca.", "tupper": false, "active": true, "sort": 108}, {"id": "rl10", "slot": "cena", "mode": "sencilla", "name": "Pollo desmechado con salsa de yogur", "items": [["pollo", "p"], ["verduras", 180], ["yogurProt", 60], ["aove", "f"]], "how": "Pollo cocido o a la plancha desmechado con dos tenedores. Zanahoria rallada, lechuga y una cucharada de yogur con ajo en polvo, perejil y sal como salsa. Para la salsa, yogur natural o proteico sin azúcar añadido.", "steps": [], "plate": "", "tupper": true, "active": true, "sort": 109}, {"id": "rl11", "slot": "cena", "mode": "sencilla", "name": "Ternera picada con cherrys", "items": [["terneraPicada", "p"], ["verduras", 150], ["aove", "f"]], "how": "Dora la carne picada a fuego fuerte sin removerla mucho para que quede tostadita. Sirve con cherrys con orégano y lechuga.", "steps": [], "plate": "", "tupper": false, "active": true, "sort": 110}, {"id": "rl12", "slot": "comida", "mode": "sencilla", "name": "Ternera, cottage y aguacate", "items": [["terneraPicada", "p"], ["cottage", 100], ["aguacate", "f"]], "how": "Carne picada bien dorada con sal y pimienta, cottage al lado y aguacate en gajos con sal en escamas. Sin cocinar casi nada y con mucha proteína. Cottage y carne picada: mira la etiqueta, que la carne sea magra (máx. 10% de grasa).", "steps": [], "plate": "", "tupper": false, "active": true, "sort": 111}, {"id": "rl13", "slot": "desayuno", "mode": "sencilla", "name": "Burger, huevos y kiwi", "items": [["hambTernera", "p"], ["huevo", 120], ["kiwi", "c"]], "how": "Hamburguesa a la plancha 3–4 minutos por lado, huevos a la plancha o revueltos en la misma sartén y kiwi en rodajas. Desayuno salado que sacia hasta la comida. Hamburguesa con un 90% de carne como mínimo y sin fécula, almidón ni rellenos (mira los ingredientes).", "steps": [], "plate": "", "tupper": false, "active": true, "sort": 112}, {"id": "rl14", "slot": "merienda", "mode": "sencilla", "name": "Yogur rosa de fresas y chía", "items": [["yogurProt", "p"], ["fresas", "c"], ["frutosRojos", 50], ["chia", 10], ["proteina", 10]], "how": "Yogur de fresa o natural, fresas en láminas, frutos rojos congelados, chía y un poco de proteína espolvoreada por encima. Si el yogur es de fresa, que sea sin azúcares añadidos.", "steps": [], "plate": "", "tupper": false, "active": true, "sort": 113}, {"id": "rl15", "slot": "pre", "mode": "sencilla", "name": "Plátano y dátiles antes de entrenar", "items": [["platano", "c"], ["datiles", 20]], "how": "Un plátano y un par de dátiles 30–45 minutos antes de entrenar. Energía rápida y nada pesada.", "steps": [], "plate": "", "tupper": false, "active": true, "sort": 114}, {"id": "rl16", "slot": "desayuno", "mode": "sanji", "name": "Crepe proteica de frutos rojos", "items": [["avena", "c"], ["claras", "p"], ["proteina", 15], ["yogurProt", 100], ["frutosRojos", 80]], "how": "", "steps": ["Tritura la avena con las claras, la proteína y unos cuantos frutos rojos hasta tener una masa líquida.", "Sartén antiadherente grande a fuego medio, vierte toda la masa y extiéndela como una crepe. Vuelta cuando se despegue.", "Cubre con el yogur, el resto de frutos rojos y un poco de proteína espolvoreada."], "plate": "", "tupper": false, "active": true, "sort": 115}, {"id": "rl17", "slot": "desayuno", "mode": "sanji", "name": "Brunch completo de domingo", "items": [["huevo", 120], ["panIntegral", "c"], ["pollo", "p"], ["aguacate", "f"], ["yogurProt", 125], ["arandanos", 50]], "how": "", "steps": ["Tuesta el pan y úntalo con el aguacate machacado con sal y pimienta.", "Pon por encima el pollo desmechado.", "Revuelve los huevos a fuego bajo para que queden jugosos.", "Al lado, yogur con arándanos y canela."], "plate": "Plato grande con el revuelto y la tostada, y el yogur en un bol aparte.", "tupper": false, "active": true, "sort": 116}]$arc$::jsonb)
on conflict (id) do update set name = excluded.name, items = excluded.items, how = excluded.how, steps = excluded.steps, plate = excluded.plate, tupper = excluded.tupper;

-- Consejos en recetas que ya existían (fiambre al 90% y tortitas sin aditivos)
update public.content_recipes set how = 'Tuesta el pan, ralla tomate por encima, un chorrito de aceite y el pavo. El pavo, con un 90% de carne como mínimo.' where id = 'r001';
update public.content_recipes set how = 'Unta el queso crema en las tortitas y pon el jamón encima. Tortitas sin aditivos: solo arroz o maíz y sal.' where id = 'r012';
update public.content_recipes set how = 'Aguacate machacado sobre las tortitas y el pavo encima. Fiambre con un 90% de carne como mínimo y tortitas sin aditivos (solo arroz o maíz y sal).' where id = 'r029';
